opx('get', '/api/v1/external-agent/reference', 'getExternalAgentReference', CT, 'Referencia para el agente externo', [], ['store', 'product_group', 'meal_slot'], resp='ExternalAgentReference', desc=EXTD + 'Devuelve los ids de tiendas, grupos de producto y tiempos de comida con los que el agente arma sus lotes. Solo lectura.' + EXTP)
